INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DIN-14021', '2016', 'CLAIMMAP', 'Aussagetyp → Abschnitt 7 (Voraussetzung, Bewertungsverfahren) — je Aussagetyp die gedruckte Bedingung und der benötigte Zahlenblock', '§7.2–§7.17 (§5.1 für sonstige Umweltaussagen)', NULL, ARRAY['claim_type']::text[], '[{"name":"clause","type":"string"},{"name":"numeric_block","type":"enum"},{"name":"condition_text","type":"string"},{"name":"comparative_by_clause","type":"boolean"}]'::jsonb, 'locked', '7.1.1 Abschnitt 7 gibt Erklärungen und Anwendungshinweise für ausgewählte, häufig in umweltbezogenen Anbietererklärungen verwendete Begriffe. Die Verantwortung des Antragstellers, den in diesem Abschnitt dargelegten Prinzipien zu folgen, darf nicht durch Verwendung ähnlicher Begriffe abgeschwächt werden. Abschnitt 7 ergänzt, ersetzt jedoch nicht die Anforderungen in anderen Abschnitten der vorliegenden Internationalen Norm. — a) Die Aussage darf nur erfolgen, wenn $R-E>0$.', 'md_verified')
