SELECT id, 'compostable', '{"claim_type":"compostable"}'::jsonb, NULL, 'kompostierbar', 0, '{"clause":"7.2.2.1","numeric_block":"none","condition_text":"7.2.2.1 Eine Aussage zur Kompostierbarkeit darf nicht erfolgen, wenn ein Produkt, eine Verpackung oder ein Produkt- oder Verpackungsbestandteil: a) den Gesamtnutzen des Komposts als Bodenverbesserungsmittel negativ beeinflusst; b) zu irgendeinem Zeitpunkt der Zersetzung oder danach Stoffe in gefährlichen Konzentrationen an die Umwelt abgibt; oder c) die Zersetzungsgeschwindigkeit in derartigen Systemen, in denen das Produkt oder der Bestandteil möglicherweise kompostiert wird, beträchtlich verringert.","comparative_by_clause":false}'::jsonb, '7.2.2.1 Eine Aussage zur Kompostierbarkeit darf nicht erfolgen, wenn ein Produkt, eine Verpackung oder ein Produkt- oder Verpackungsbestandteil:
a) den Gesamtnutzen des Komposts als Bodenverbesserungsmittel negativ beeinflusst;
b) zu irgendeinem Zeitpunkt der Zersetzung oder danach Stoffe in gefährlichen Konzentrationen an die Umwelt abgibt; oder
c) die Zersetzungsgeschwindigkeit in derartigen Systemen, in denen das Produkt oder der Bestandteil möglicherweise kompostiert wird, beträchtlich verringert.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'CLAIMMAP'
