SELECT id, 'degradable', '{"claim_type":"degradable"}'::jsonb, NULL, 'abbaubar', 1, '{"clause":"7.3.2.1 a)","numeric_block":"none","condition_text":"7.3.2.1 Die folgenden Voraussetzungen beziehen sich auf alle Abbauarten, z. B. den biologischen und den Photoabbau. a) Aussagen zur Abbaubarkeit dürfen nur in Bezug auf ein bestimmtes Prüfverfahren erfolgen, das den zu erreichenden Abbaugrad und die Testdauer einschließt, und sie müssen für die Umstände zutreffen, unter denen das Produkt oder die Verpackung voraussichtlich entsorgt wird. b) Es darf keine Aussage zur Abbaubarkeit für ein Produkt oder eine Verpackung oder einen Bestandteil eines Produktes oder einer Verpackung erfolgen, die Stoffe in gefährlichen Konzentrationen an die Umwelt abgeben.","comparative_by_clause":false}'::jsonb, '7.3.2.1 Die folgenden Voraussetzungen beziehen sich auf alle Abbauarten, z. B. den biologischen und den Photoabbau.
a) Aussagen zur Abbaubarkeit dürfen nur in Bezug auf ein bestimmtes Prüfverfahren erfolgen, das den zu erreichenden Abbaugrad und die Testdauer einschließt, und sie müssen für die Umstände zutreffen, unter denen das Produkt oder die Verpackung voraussichtlich entsorgt wird.
b) Es darf keine Aussage zur Abbaubarkeit für ein Produkt oder eine Verpackung oder einen Bestandteil eines Produktes oder einer Verpackung erfolgen, die Stoffe in gefährlichen Konzentrationen an die Umwelt abgeben.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'CLAIMMAP'
