SELECT id, 'recyclable', '{"claim_type":"recyclable"}'::jsonb, NULL, 'recyclingfähig', 5, '{"clause":"7.7.2","numeric_block":"none","condition_text":"Falls keine Sammelstellen oder Sammeleinrichtungen für das Recycling des Produktes oder der Verpackung für einen angemessenen Anteil an Käufern, potentiellen Käufern oder Anwendern des Produktes in verkehrsgünstiger Lage zur Verfügung stehen, gilt Folgendes: a) Es muss eine konkrete Aussage zur Recyclingfähigkeit erfolgen. b) Die konkrete Aussage muss in geeigneter Weise auf die begrenzte Verfügbarkeit von Sammelstellen und Sammeleinrichtungen hinweisen. c) Verallgemeinerte Bezeichnungen wie „Recyclingfähig, wenn Einrichtungen vorhanden sind\", die nicht auf die begrenzte Verfügbarkeit von Sammelstellen und Sammeleinrichtungen hinweisen, sind nicht zulässig.","comparative_by_clause":false}'::jsonb, 'Falls keine Sammelstellen oder Sammeleinrichtungen für das Recycling des Produktes oder der Verpackung für einen angemessenen Anteil an Käufern, potentiellen Käufern oder Anwendern des Produktes in verkehrsgünstiger Lage zur Verfügung stehen, gilt Folgendes:
a) Es muss eine konkrete Aussage zur Recyclingfähigkeit erfolgen.
b) Die konkrete Aussage muss in geeigneter Weise auf die begrenzte Verfügbarkeit von Sammelstellen und Sammeleinrichtungen hinweisen.
c) Verallgemeinerte Bezeichnungen wie „Recyclingfähig, wenn Einrichtungen vorhanden sind", die nicht auf die begrenzte Verfügbarkeit von Sammelstellen und Sammeleinrichtungen hinweisen, sind nicht zulässig.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'CLAIMMAP'
