SELECT id, 'waste_reduction', '{"claim_type":"waste_reduction"}'::jsonb, NULL, 'Abfallminderung', 16, '{"clause":"7.13.2.1","numeric_block":"none","condition_text":"7.13.2.1 Alle Aussagen zur Abfallminderung müssen begründet sein. Weil Abfallminderung eine vergleichende Aussage ist, müssen die Anforderungen von 6.3 erfüllt sein.","comparative_by_clause":true}'::jsonb, '7.13.2.1 Alle Aussagen zur Abfallminderung müssen begründet sein. Weil Abfallminderung eine vergleichende Aussage ist, müssen die Anforderungen von 6.3 erfüllt sein.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'CLAIMMAP'
