INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'renewable_material', '{"claim_type":"renewable_material"}'::jsonb, NULL, 'Erneuerbares Material', 17, '{"clause":"7.14.2","numeric_block":"renewable_material","condition_text":"Eine uneingeschränkte Aussage zur Erneuerbarkeit ist nur zulässig, wenn das Produkt zu 100 \\% aus erneuerbarem Material besteht, wobei nur geringfügige Anteile an nicht erneuerbarem Material in diesem Material erlaubt sind. Andernfalls müssen Aussagen zur Erneuerbarkeit wie folgt eingeschränkt werden: a) wenn eine Aussage zum Gehalt an erneuerbarem Material gemacht wird, muss der prozentuale Massenanteil von erneuerbarem Material angegeben werden; b) der prozentuale Anteil von erneuerbarem Material (Massenanteil) in Produkten und in Verpackungen muss getrennt angegeben werden und darf nicht zusammengefasst werden.","comparative_by_clause":false}'::jsonb, 'Eine uneingeschränkte Aussage zur Erneuerbarkeit ist nur zulässig, wenn das Produkt zu 100 \% aus erneuerbarem Material besteht, wobei nur geringfügige Anteile an nicht erneuerbarem Material in diesem Material erlaubt sind. Andernfalls müssen Aussagen zur Erneuerbarkeit wie folgt eingeschränkt werden:
a) wenn eine Aussage zum Gehalt an erneuerbarem Material gemacht wird, muss der prozentuale Massenanteil von erneuerbarem Material angegeben werden;
b) der prozentuale Anteil von erneuerbarem Material (Massenanteil) in Produkten und in Verpackungen muss getrennt angegeben werden und darf nicht zusammengefasst werden.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'CLAIMMAP'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'renewable_energy', '{"claim_type":"renewable_energy"}'::jsonb, NULL, 'Erneuerbare Energie', 18, '{"clause":"7.15.2","numeric_block":"renewable_energy","condition_text":"Eine uneingeschränkte Aussage zur erneuerbaren Energie ist nur zulässig, wenn 100 \\% der Energie erneuerbar ist. Andernfalls müssen Aussagen zur erneuerbaren Energie wie folgt eingeschränkt werden.","comparative_by_clause":false}'::jsonb, 'Eine uneingeschränkte Aussage zur erneuerbaren Energie ist nur zulässig, wenn 100 \% der Energie erneuerbar ist. Andernfalls müssen Aussagen zur erneuerbaren Energie wie folgt eingeschränkt werden.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'CLAIMMAP'
