SELECT id, 'sustainable', '{"claim_type":"sustainable"}'::jsonb, NULL, 'Nachhaltig', 19, '{"clause":"7.16.1","numeric_block":"none","condition_text":"Wie in 5.5 angeführt, darf keine Anbietererklärung über das Erreichen von Nachhaltigkeit abgegeben werden. Im vorliegenden Unterabschnitt wird nochmals betont, dass uneingeschränkte Anbietererklärungen zu „nachhaltig“ und „Nachhaltigkeit\" nicht verwendet werden dürfen.","comparative_by_clause":false}'::jsonb, 'Wie in 5.5 angeführt, darf keine Anbietererklärung über das Erreichen von Nachhaltigkeit abgegeben werden. Im vorliegenden Unterabschnitt wird nochmals betont, dass uneingeschränkte Anbietererklärungen zu „nachhaltig“ und „Nachhaltigkeit" nicht verwendet werden dürfen.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'CLAIMMAP'
