SELECT id, 'f', '{"item":"f"}'::jsonb, NULL, 'f) sofern die umweltbezogene Anbietererklärung einen Vergleich mit anderen Produkten enthält, eine eindeutige Beschreibung des angewendeten Verfahrens, der Ergebnisse von Prüfungen dieser Produkte und alle Annahmen;', 5, '{"letter":"f)","text":"sofern die umweltbezogene Anbietererklärung einen Vergleich mit anderen Produkten enthält, eine eindeutige Beschreibung des angewendeten Verfahrens, der Ergebnisse von Prüfungen dieser Produkte und alle Annahmen;"}'::jsonb, 'f) sofern die umweltbezogene Anbietererklärung einen Vergleich mit anderen Produkten enthält, eine eindeutige Beschreibung des angewendeten Verfahrens, der Ergebnisse von Prüfungen dieser Produkte und alle Annahmen;' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'S6_5_3'
