INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'g', '{"item":"g"}'::jsonb, NULL, 'g) Nachweis, dass die Bewertung des Antragstellers die Gewissheit bietet, dass die umweltbezogene Anbietererklärung während des Zeitraumes, für den das Produkt auf dem Markt angeboten wird, und für einen angemessenen Zeitraum danach weiterhin richtig ist, wobei die Lebensdauer des Produktes zu berücksichtigen ist.', 6, '{"letter":"g)","text":"Nachweis, dass die Bewertung des Antragstellers die Gewissheit bietet, dass die umweltbezogene Anbietererklärung während des Zeitraumes, für den das Produkt auf dem Markt angeboten wird, und für einen angemessenen Zeitraum danach weiterhin richtig ist, wobei die Lebensdauer des Produktes zu berücksichtigen ist."}'::jsonb, 'g) Nachweis, dass die Bewertung des Antragstellers die Gewissheit bietet, dass die umweltbezogene Anbietererklärung während des Zeitraumes, für den das Produkt auf dem Markt angeboten wird, und für einen angemessenen Zeitraum danach weiterhin richtig ist, wobei die Lebensdauer des Produktes zu berücksichtigen ist.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'S6_5_3'
