INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DIN-14021', '2016', 'S5_3_5_10', 'Anforderungen an alle umweltbezogenen Anbietererklärungen — die Abschnitte 5.3 bis 5.10 als Prüfliste', '§5.3–§5.10', NULL, ARRAY['clause']::text[], '[{"name":"clause_printed","type":"string"},{"name":"heading","type":"string"},{"name":"requirement_text","type":"string"}]'::jsonb, 'locked', 'Umweltbezogene Anbietererklärungen und ergänzende Erklärungen sind Gegenstand aller Anforderungen in 5.7. Derartige Aussagen, einschließlich jeder ergänzenden Erklärung: — Eine unbestimmte oder unspezifische Umweltaussage oder eine, die allgemein darauf abzielt, dass ein Produkt günstig für die Umwelt oder umweltverträglich ist, darf nicht gemacht werden. Deshalb dürfen keine Umweltaussagen wie „umweltsicher“, „umweltfreundlich“, „freundlich zur Erde", „ohne Emissionen“, „grün“, „naturfreundlich" und „ozonfreundlich“ verwendet werden.', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, '5_3', '{"clause":"5_3"}'::jsonb, NULL, '5.3 Unbestimmte oder unspezifische Aussagen', 0, '{"clause_printed":"5.3","heading":"5.3 Unbestimmte oder unspezifische Aussagen","requirement_text":"Eine unbestimmte oder unspezifische Umweltaussage oder eine, die allgemein darauf abzielt, dass ein Produkt günstig für die Umwelt oder umweltverträglich ist, darf nicht gemacht werden. Deshalb dürfen keine Umweltaussagen wie „umweltsicher“, „umweltfreundlich“, „freundlich zur Erde\", „ohne Emissionen“, „grün“, „naturfreundlich\" und „ozonfreundlich“ verwendet werden."}'::jsonb, 'Eine unbestimmte oder unspezifische Umweltaussage oder eine, die allgemein darauf abzielt, dass ein Produkt günstig für die Umwelt oder umweltverträglich ist, darf nicht gemacht werden. Deshalb dürfen keine Umweltaussagen wie „umweltsicher“, „umweltfreundlich“, „freundlich zur Erde", „ohne Emissionen“, „grün“, „naturfreundlich" und „ozonfreundlich“ verwendet werden.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'S5_3_5_10'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, '5_4', '{"clause":"5_4"}'::jsonb, NULL, '5.4 Aussagen von „... frei“', 1, '{"clause_printed":"5.4","heading":"5.4 Aussagen von „... frei“","requirement_text":"Eine Aussage von „... frei“ darf nur gemacht werden, wenn der Anteil des bestimmten Stoffes nicht größer ist als der, der als anerkannte Spurenverunreinigung oder natürliche Grundbelastung vorzufinden wäre."}'::jsonb, 'Eine Aussage von „... frei“ darf nur gemacht werden, wenn der Anteil des bestimmten Stoffes nicht größer ist als der, der als anerkannte Spurenverunreinigung oder natürliche Grundbelastung vorzufinden wäre.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'S5_3_5_10'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, '5_5', '{"clause":"5_5"}'::jsonb, NULL, '5.5 Aussagen zur Nachhaltigkeit', 2, '{"clause_printed":"5.5","heading":"5.5 Aussagen zur Nachhaltigkeit","requirement_text":"Konzepte im Zusammenhang mit Nachhaltigkeit sind äußerst kompliziert und werden noch untersucht. Gegenwärtig gibt es keine bestimmten Verfahren zur Messung von Nachhaltigkeit oder zu ihrer Bestätigung. Deshalb darf keine Aussage über das Erreichen von Nachhaltigkeit gemacht werden."}'::jsonb, 'Konzepte im Zusammenhang mit Nachhaltigkeit sind äußerst kompliziert und werden noch untersucht. Gegenwärtig gibt es keine bestimmten Verfahren zur Messung von Nachhaltigkeit oder zu ihrer Bestätigung. Deshalb darf keine Aussage über das Erreichen von Nachhaltigkeit gemacht werden.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'S5_3_5_10'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, '5_6', '{"clause":"5_6"}'::jsonb, NULL, '5.6 Anwendung von ergänzenden Erklärungen', 3, '{"clause_printed":"5.6","heading":"5.6 Anwendung von ergänzenden Erklärungen","requirement_text":"Umweltbezogene Anbietererklärungen müssen mit einer ergänzenden Erklärung verbunden sein, wenn die Aussage allein möglicherweise zu Missverständnissen führen kann. Eine Umweltaussage darf nur dann ohne ergänzende Erklärung erfolgen, wenn sie unter allen vorhersehbaren Umständen ohne Einschränkungen gültig ist."}'::jsonb, 'Umweltbezogene Anbietererklärungen müssen mit einer ergänzenden Erklärung verbunden sein, wenn die Aussage allein möglicherweise zu Missverständnissen führen kann. Eine Umweltaussage darf nur dann ohne ergänzende Erklärung erfolgen, wenn sie unter allen vorhersehbaren Umständen ohne Einschränkungen gültig ist.' FROM regulation_tables WHERE standard_code = 'DIN-14021' AND edition = '2016' AND table_code = 'S5_3_5_10'
